void NameEntryMenu::OnActivate()
{
	FEMultiMenu::OnActivate();
	if (g_game_ptr->get_game_mode() == 0)
	{
		name->changeText(g_career->GetInitials());
		if (name->getText().length() > 0)
			setHigh(entry[39]);
		else 
			setHigh(entry[0]);
	}
	else
		name->changeText("");
	name_count = name->getText().length();
	name_entered = false;

}
